const menu=document.querySelector('.menu');
const nav=document.querySelector('.navlinks');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');menu.focus()}});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('[data-category]').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter)}));
const form=document.querySelector('#brief');
if(form){const params=new URLSearchParams(location.search);for(const [param,id] of [['offre','offer'],['secteur','sector']]){const el=document.getElementById(id);if([...el.options].some(x=>x.value===params.get(param)))el.value=params.get(param)}let message='';form.addEventListener('submit',async event=>{event.preventDefault();const f=new FormData(form);message=`Bonjour WEB AFRICA,\n\nJe souhaite un devis pour mon projet.\nNom : ${f.get('name')}\nEntreprise : ${f.get('company')||'À préciser'}\nSecteur : ${f.get('sector')}\nBesoin : ${f.get('offer')}\nBudget : ${f.get('budget')}\nDélai : ${f.get('deadline')||'À préciser'}\n\n${f.get('message')}`;document.getElementById('brief-text').textContent=message;document.getElementById('send-wa').href='https://wa.me/22669291337?text='+encodeURIComponent(message);document.getElementById('send-mail').href='mailto:abdousalamkoanda@gmail.com?subject='+encodeURIComponent('Demande de devis — WEB AFRICA')+'&body='+encodeURIComponent(message);const result=document.getElementById('result');result.hidden=false;result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});document.getElementById('copy-status').textContent=''});document.getElementById('copy-brief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(message);document.getElementById('copy-status').textContent='Demande copiée.'}catch{document.getElementById('copy-status').textContent='La copie automatique est indisponible. Sélectionnez le texte de votre demande pour le copier.'}})}
